/bin/bash -lc "python3 - <<'PY'
from zipfile import ZipFile
from xml.etree import ElementTree as ET
path='/home/user/Student_Grades_and_Remarks.xlsx'
ns={'a':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
with ZipFile(path) as z:
    shared=[]
    if 'xl/sharedStrings.xml' in z.namelist():
        root=ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('a:si', ns):
            texts=[]
            for t in si.findall('.//a:t', ns):
                texts.append(t.text or '')
            shared.append(''.join(texts))
    sheet=ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
    vals={}
    for c in sheet.findall('.//a:c', ns):
        r=c.attrib.get('r')
        if r and r.startswith('F') and r[1:].isdigit() and 10 <= int(r[1:]) <= 22:
            t=c.attrib.get('t')
            v=c.find('a:v', ns)
            isel=c.find('a:is', ns)
            if t=='s' and v is not None:
                vals[r]=shared[int(v.text)]
            elif t=='inlineStr' and isel is not None:
                vals[r]=''.join((x.text or '') for x in isel.findall('.//a:t', ns))
            elif v is not None:
                vals[r]=v.text
    for row in range(10,23):
        print(f'F{row}: {vals.get(f\"F{row}\")}')
PY"

